+  final code = await f.dispatcher.dispatch([
+    'compile',
+    entry.path,
+    '--agent-root',
+    f.agentRoot.path,
+    '--versions-file',
+    versionsFile.path,
+    '--out',
+    f.outDir.path,
+  ]);
+  expect(code, 0);
+  return File('${f.outDir.path}/my_agent-2.3.4.zip');
+}
