+      write('js/main.js', "var c = require('./common/commentMarkup.js');\n");
+      final entry = write(
+          'commented.json',
+          jsonEncode({
+            'name': 'X',
+            'params': {'jsPath': 'agents/js/main.js'},
+          }));
+      final names = zipNames(compileAgent(entry).zipFile);
+      expect(names, contains('js/common/commentMarkup.js'));
