+      final r2 = AgentPackCompiler(agentRoot.path)
+          .compile(entry, '1.0.0', 'abc', out2);
+      expect(r1.zipFile.readAsBytesSync(), r2.zipFile.readAsBytesSync());
+      out1.deleteSync(recursive: true);
+      out2.deleteSync(recursive: true);
