+          }));
+      final names = zipNames(compileAgent(entry).zipFile);
+      expect(names, contains('scripts/run-agent.sh'));
+      expect(names, contains('scripts/providers/_common.sh'));
+      expect(names, contains('scripts/providers/claude.sh'));
+    });
