+    test('shell scripts carry 0755 mode in the manifest', () {
+      write('scripts/run-agent.sh', '#!/bin/bash\necho hi\n');
+      final entry = write(
+          'mode_agent.json',
+          jsonEncode({
+            'name': 'X',
+            'params': {
+              'cliCommands': ['./agents/scripts/run-agent.sh']
