+          version,
+          _optionValue(rest, '--source-commit') ??
+              _detectSourceCommit(agentRoot),
+          Directory(_optionValue(rest, '--out') ?? 'dist'));
+      _printCompileResult(agentName, version, result);
+      return 0;
