+      expect(code, 0);
+      expect(f.lines.join('\n'), contains('Agent pack built successfully'));
+      expect(File('${f.outDir.path}/my_agent-1.0.0.zip').existsSync(), isTrue);
+      expect(File('${f.outDir.path}/manifest.json').existsSync(), isTrue);
+      expect(
