        Files.write(shaFile.toPath(), (sha256Hex(zipFile) + "  " + zipFile.getName() + "\n").getBytes(StandardCharsets.UTF_8));

        logger.info("Pack built: {} ({} files)", zipFile.getName(), closure.size());
