            JobParams jobParams = processor.processRunCommand(args);
            Object result = new JobRunner().run(jobParams);
            if (result == null) {
                System.err.println("Execution result of '" + jobParams.getName() + "' is null.");
            } else {
                System.out.println(JSONUtils.serializeResult(result));
                return;
            }
            System.exit(1);
        }
        if ("interactive".equals(firstArg) || "i".equals(firstArg)) {
            launchInteractive();
            return;
        }
        if ("compile".equals(firstArg)) {
            // Build a versioned agent pack (zip + manifest + sha256) — dm.ai #595.
            new CompileCommand().run(java.util.Arrays.copyOfRange(args, 1, args.length));
            return;
        }
