  final fileComment = fileData.comment ?? '';

  final encodedFilename = filenameEncoding.encode(fileData.name);
  final encodedFileComment = filenameEncoding.encode(fileComment);

  output.writeUint32(ZipFileHeader.SIGNATURE);
